{
  "promos": [
    {
      "title": "The Trial of Lady Juliana",
      "start_block": "B002",
      "end_block": "B047",
      "hook": "Judge's booming voice: 'Lady Juliana Ashcroft, you are accused of witchcraft, unlawful healing, and poisoning.'",
      "cliffhanger": "The Lord triumphantly declares 'the witness has confirmed the ritual' after Prudence's tearful false testimony, leaving Juliana's fate hanging.",
      "why": "Opens with a shocking accusation, builds through coerced testimony and Juliana's defiant 'It was not a ritual!', cuts before any defense or verdict.",
      "context_gap": "Why Prudence is forced to lie and who the Lord is."
    },
    {
      "title": "She Refuses to Repent",
      "start_block": "B071",
      "end_block": "B102",
      "hook": "Juliana's incisive challenge: 'What were their illnesses?' cutting through the Lord's poisoning accusation.",
      "cliffhanger": "Juliana's fearless 'Then let it be' as the Judge warns refusal is proof of witchcraft, leaving her condemned by her own integrity.",
      "why": "Escalates from Juliana's fierce defense of herbal medicine to her unflinching acceptance of a death sentence, ending on her proud defiance.",
      "context_gap": "The full history of her healing work and the conspiracy against her."
    },
    {
      "title": "The Judge's Final Judgment",
      "start_block": "B105",
      "end_block": "B116",
      "hook": "Juliana's passionate declaration: 'I will not call healing evil just because powerful people have decided to fear it.'",
      "cliffhanger": "The Judge extends his raised hand in judgment over Juliana as the scene fades to black, leaving the sentence unspoken.",
      "why": "Ends the episode on the ultimate unresolved beat—the verdict about to be delivered—with Juliana standing unbroken.",
      "context_gap": "What the actual sentence will be."
    }
  ],
  "moments": [
    {
      "start_block": "B002",
      "end_block": "B008",
      "kind": "hook",
      "description": "Judge accuses Lady Juliana of witchcraft and poisoning; she calmly answers 'No' to possessing the book."
    },
    {
      "start_block": "B017",
      "end_block": "B021",
      "kind": "emotional",
      "description": "Juliana proudly declares 'I admit to healing the sick' as the Judge furiously slams his gavel and shouts 'Silence!'"
    },
    {
      "start_block": "B048",
      "end_block": "B054",
      "kind": "hook",
      "description": "Juliana slams her cuffed hands and shouts 'It was not a ritual!' as the Judge bellowingly silences her."
    },
    {
      "start_block": "B094",
      "end_block": "B102",
      "kind": "cliffhanger",
      "description": "Juliana refuses to renounce her practices, saying 'Then let it be' as the Judge warns it proves witchcraft."
    }
  ]
}
